// Calculate squared distance between particles
float dx = pi->x - pj->x;
float dy = pi->y - pj->y;
float dz = pi->z - pj->z;
float r2 = dx * dx + dy * dy + dz * dz;

// Check if within smoothing radius
if (r2 < h2) {
    // Calculate Poly6 kernel contribution: (h2 - r2)^3
    float q = h2 - r2;
    float q3 = q * q * q;

    // Accumulate density contribution
    density += massPoly6 * q3;
}

